/* Paper 2 exam sprint: supplemental original educational questions, not Wits past questions.
   Scope: existing student paper split; format: Wits Integrated EYA guide pp.1–3, Example IEYA.
   Foundations: existing core notes, supplementary clinical knowledge. Clinical reference for local treatment: https://www.health.gov.za/nhi-edp-stgs-eml/ (confirm specific regimens with lecturer/local protocol). */
(function(){
"use strict";
const rows=[["Acute Kidney Injury","After fluid loss with hypotension, no pulmonary oedema, which initial treatment is appropriate?","Isotonic crystalloid:Restores renal perfusion in hypovolaemia.","Loop diuretic:May worsen volume depletion.","ACE inhibitor:Lowers efferent arteriolar tone and GFR.","Dopamine infusion:Low-dose dopamine does not protect kidneys.","What tubular lesion follows prolonged renal ischaemia?","Acute tubular injury;Acute tubular necrosis;ATN","Prerenal: low perfusion; prolonged ischaemia → tubular injury. Muddy brown casts suggest ATN. Bedside urine dipstick, urine output and bladder scan; check potassium and ECG. Stop nephrotoxins under supervision."],["Chronic Kidney Disease","In stable albuminuric CKD with hypertension and normal potassium, which class reduces intraglomerular pressure?","ACE inhibitor:Reduces efferent arteriolar tone and albuminuria; monitor creatinine and potassium.","Loop diuretic:Useful for congestion, not the same antiproteinuric mechanism.","Beta blocker:Reduces heart rate and renin, not the preferred mechanism here.","Alpha blocker:Reduces vascular resistance, not the same renal protection.","Which renal hormone deficiency contributes to anaemia?","Erythropoietin;EPO","CKD ≥3 months; low EPO → normocytic anaemia; low calcitriol and phosphate retention → secondary hyperparathyroidism. Avoid NSAIDs; check eGFR and urine ACR."],["Congestive Cardiac Failure","With pulmonary congestion and peripheral oedema, which class provides rapid symptomatic decongestion?","Loop diuretic:Increases sodium and water excretion.","Beta blocker:Chronic disease-modifying therapy, not rapid decongestion.","ACE inhibitor:Reduces afterload and remodelling, not direct rapid diuresis.","Mineralocorticoid antagonist:Useful in selected chronic HF, not primary rapid decongestion.","Which neurohormonal system drives sodium retention?","RAAS;Renin angiotensin aldosterone system","Raised venous hydrostatic pressure causes oedema; low effective arterial volume activates RAAS. Daily weight and salt counselling; escalate hypoxia or shock."],["Hypertension","In an adult with hypertension and albuminuric CKD, no pregnancy or hyperkalaemia, which class is particularly appropriate?","ACE inhibitor:Reduces BP and albuminuria; monitor renal function and potassium.","Alpha blocker:Not preferred for albuminuric renal protection.","Loop diuretic:Useful with overload, not preferred solely for albuminuria.","Beta blocker:Useful for specific cardiac indications.","What urinary measure quantifies albumin leakage?","Albumin creatinine ratio;ACR;Urine ACR","Confirm repeated BP; hypertensive emergency requires acute organ damage, not BP alone. Lifestyle: reduce salt, exercise, stop smoking. First-line depends on comorbidities and local protocol."],["Nephritic syndrome","A patient has cola urine and hypertension. Which urine finding localises bleeding to glomeruli?","Red cell casts:Form when RBCs become trapped in tubular uromodulin.","White cell casts:Suggest tubulointerstitial inflammation or pyelonephritis.","Hyaline casts:May occur with dehydration or exercise.","Calcium oxalate crystals:May suggest stone risk but not glomerular bleeding.","What hypersensitivity mechanism typifies post-streptococcal GN?","Type III;Immune complex deposition","Haematuria, dysmorphic RBCs, RBC casts, oliguria and hypertension. C3 may be low in postinfectious GN. Treat underlying cause; manage fluid/BP under supervision."],["Nephrotic syndrome","A patient with severe proteinuria develops a painful swollen leg. Loss of which protein contributes to thrombosis?","Antithrombin:Urinary loss contributes to hypercoagulability.","Albumin:Loss lowers oncotic pressure and causes oedema.","Transferrin:Loss may alter iron transport.","Immunoglobulin:Loss may increase infection susceptibility.","What is the specialised glomerular cell with foot processes?","Podocyte;Podocytes","Heavy proteinuria, hypoalbuminaemia, oedema, hyperlipidaemia. Podocyte barrier injury; thrombosis and infection risk. ACEi/ARB for proteinuria when appropriate; cause-specific treatment."],["Prostate Cancer","An older man has a hard irregular prostate and back pain. Which finding requires urgent escalation?","New saddle anaesthesia:Suggests cauda equina or spinal compression.","Stable nocturia:Common lower urinary tract symptom.","Mild urinary hesitancy:May accompany benign enlargement.","Gradual erectile dysfunction:Needs evaluation but is not the immediate neurological threat.","What type of bone metastasis is classically associated?","Osteoblastic;Sclerotic;Osteoblastic metastases","PSA is not cancer-specific; DRE may reveal hard irregular prostate. Androgen deprivation is a class of therapy for advanced disease, not universal first-line. New neurological deficits → urgent referral."],["Renal Calculi","In uncomplicated renal colic with preserved renal function and no contraindication, which analgesic class is usually preferred?","NSAID:Reduces prostaglandin-mediated ureteric pressure and pain.","Opioid:Alternative when NSAIDs are unsuitable or inadequate.","Antimuscarinic:May reduce bladder spasm but not preferred for colic.","Corticosteroid:Not routine analgesia for renal colic.","Most common kidney stone composition?","Calcium oxalate","Colicky flank-to-groin pain, haematuria; urine dipstick and pregnancy test where relevant. Fever plus obstruction is an emergency; analgesia and urgent decompression referral."],["Sepsis","After adequate fluid resuscitation, hypotension persists in septic shock. Which vasopressor is preferred under senior care?","Noradrenaline:Predominantly alpha-mediated vasoconstriction restores MAP.","Dobutamine:Inotrope for selected low-output states.","Nitroglycerin:Vasodilates and can worsen hypotension.","Furosemide:Diuresis does not correct distributive shock.","Which cell-wall component of Gram-negative bacteria activates TLR4?","Lipopolysaccharide;LPS;Endotoxin","Dysregulated host response → organ dysfunction; lactate, perfusion, urine output. Early appropriate IV antimicrobials and source control; cultures if no delay."],["Systemic Lupus Erythematosus","In stable SLE without organ-threatening activity, which background drug class is commonly used if appropriate?","Antimalarial:Hydroxychloroquine reduces flares; retinal monitoring needed.","NSAID:Symptomatic benefit but not equivalent flare prevention.","Loop diuretic:Controls oedema but not autoimmunity.","Antibiotic:Treats infection, not sterile autoimmunity.","What hypersensitivity mechanism drives typical lupus nephritis?","Type III;Immune complexes;Immune complex deposition","ANA sensitive but nonspecific; anti-dsDNA and low complement support active nephritis. Check urine protein, creatinine; avoid sun exposure; suspected renal involvement needs specialist review."],["Acute Gastroenteritis","A child with diarrhoea can drink and has no shock. What is the initial treatment?","Oral rehydration solution:Replaces electrolyte and water loss via sodium-glucose cotransport.","Antimotility agent:Not routine in children and may cause harm.","Empirical antibiotic:Not routine for uncomplicated watery diarrhoea.","Intravenous dextrose:Does not appropriately replace sodium losses alone.","Which intestinal transporter explains ORS efficacy?","SGLT1;Sodium glucose cotransporter","ORS works despite secretory diarrhoea. Assess dehydration, urine output and mental status; continue feeding and breastfeeding. Handwashing and safe water reduce transmission."],["Ascites","In stable cirrhotic ascites without AKI or severe hyperkalaemia, which diuretic class targets secondary hyperaldosteronism?","Aldosterone antagonist:Spironolactone blocks aldosterone-mediated sodium retention.","Thiazide diuretic:Not the usual mainstay for cirrhotic ascites.","Osmotic diuretic:Not routine treatment for ascites.","Carbonic anhydrase inhibitor:Not a standard ascites therapy.","What gradient suggests portal hypertensive ascites?","SAAG;Serum ascites albumin gradient","SAAG ≥11 g/L supports portal hypertension. New or worsening ascites needs diagnostic paracentesis; neutrophils ≥250/mm³ suggest SBP. Avoid NSAIDs."],["Cholecystitis","A patient has fever and persistent RUQ pain with Murphy sign. Which initial imaging is preferred?","RUQ ultrasound:Detects stones, wall thickening and pericholecystic fluid.","Plain abdominal radiograph:Most gallstones are radiolucent.","MRCP:Useful for suspected duct stones, not routine first imaging.","Upper GI endoscopy:Evaluates mucosa, not gallbladder inflammation.","Which duct is typically obstructed in acute calculous cholecystitis?","Cystic duct","Persistent RUQ pain plus fever vs short episodic biliary colic. Analgesia, IV fluids as needed, antibiotics and surgical review. Fever+jaundice+RUQ pain suggests cholangitis."],["Colorectal Cancer","An adult with iron deficiency and altered bowel habit needs investigation. Which test allows tissue diagnosis?","Colonoscopy with biopsy:Directly visualises and samples a lesion.","Faecal immunochemical test:Detects blood but cannot confirm histology.","CEA measurement:Used mainly for follow-up, not definitive diagnosis.","Abdominal ultrasound:May identify metastases but cannot biopsy colonic mucosa.","Which gene is classically lost early in adenoma-carcinoma progression?","APC;APC gene","Right-sided: occult bleeding/IDA; left-sided: altered bowel habit/obstruction. APC → KRAS → TP53 is classic pathway, not universal. Screen according to risk; obstruction/peritonism urgent."],["Constipation","An adult with uncomplicated constipation has no alarm signs or obstruction. Which drug class draws water into stool?","Osmotic laxative:Macrogol or lactulose retains luminal water.","Stimulant laxative:Increases motility rather than primarily retaining water.","Antimuscarinic:Can worsen constipation.","Opioid analgesic:Reduces intestinal motility.","What reflex promotes defecation after eating?","Gastrocolic reflex","Review opioids, anticholinergics, fluids and fibre. Bleeding, weight loss, anaemia or new bowel change → investigation. No stool/flatus with vomiting suggests obstruction."],["Diarrhoea","Profuse watery diarrhoea causes postural dizziness; oral fluids are tolerated. What replaces ongoing losses?","Oral rehydration solution:Provides water and sodium through preserved cotransport.","Loperamide alone:Reduces motility but does not replace losses.","Broad-spectrum antibiotic:Not routine for uncomplicated watery diarrhoea.","Plain water alone:Does not adequately replace electrolytes.","What acid-base disorder follows bicarbonate-rich stool loss?","Metabolic acidosis;Normal anion gap acidosis;Hyperchloraemic acidosis","Secretory persists with fasting; osmotic improves. Blood, fever, severe pain or dehydration are red flags. Stool testing targeted to severity, duration and outbreaks."],["Food Poisoning","Several people vomit two hours after eating unrefrigerated food. Which mechanism is most likely?","Preformed bacterial toxin:Short incubation supports toxin already in food.","Invasive colonic infection:Usually takes longer and may cause dysentery.","Parasite tissue invasion:Typically longer incubation.","Antibiotic-associated colitis:Requires relevant exposure and is not a shared meal pattern.","Which organism classically produces preformed heat-stable enterotoxin in food?","Staphylococcus aureus;S aureus","Rapid vomiting after food → preformed toxin (S. aureus or emetic B. cereus). Rehydration first; hand hygiene, safe storage, notify appropriate outbreak channels."],["Gallstones","In uncomplicated biliary colic without fever, renal impairment or contraindication, which analgesic class is appropriate?","NSAID:Effective for biliary colic pain.","Antibiotic:Not indicated for uncomplicated non-infected colic.","Proton pump inhibitor:Treats acid-related symptoms, not cystic duct obstruction.","Antiemetic alone:May relieve nausea but not pain.","What is the most common gallstone chemical type?","Cholesterol;Cholesterol stones","Transient cystic duct obstruction → episodic RUQ pain; normal systemic inflammatory markers often. US first; jaundice suggests duct obstruction; fever raises concern for infection."],["Gastroesophageal Reflux Disease","Typical frequent reflux without alarm features persists despite lifestyle measures. Which class most strongly suppresses gastric acid?","Proton pump inhibitor:Irreversibly inhibits parietal cell H+/K+ ATPase.","H2 receptor antagonist:Reduces histamine-mediated secretion but less potent.","Antacid:Neutralises existing acid briefly.","Prokinetic:Not routinely first choice for acid suppression.","Which epithelial change defines Barrett oesophagus?","Intestinal metaplasia;Columnar metaplasia","LES dysfunction; avoid late meals, elevate head of bed, weight reduction if appropriate. Dysphagia, bleeding or weight loss → referral. Barrett predisposes to adenocarcinoma."],["Giardiasis","Persistent greasy foul-smelling stools follow untreated water exposure. Which drug class treats symptomatic Giardia?","Nitroimidazole:Metronidazole or tinidazole disrupts parasite nucleic acids.","Macrolide:Targets bacteria, not standard Giardia therapy.","Beta-lactam:Targets bacterial cell walls.","Anthelmintic benzimidazole:Not usual first-line choice in this setting.","Which infective parasite form is swallowed?","Cyst;Cysts","Giardia duodenalis attaches to small bowel via ventral disc → malabsorption, bloating, steatorrhoea. Stool antigen/microscopy; safe water and handwashing."],["HIV/AIDS","An eligible adult starts standard dolutegravir-based ART. What drug class is dolutegravir?","Integrase inhibitor:Blocks viral DNA integration into host genome.","Protease inhibitor:Blocks viral polyprotein cleavage.","NRTI:Terminates viral DNA synthesis; includes tenofovir and lamivudine.","NNRTI:Allosterically inhibits reverse transcriptase.","Which co-receptor is commonly used by transmitted HIV?","CCR5","CD4 and CCR5/CXCR4 entry; CD4 reflects immune status, viral load response. Standard TLD when appropriate; screen for OIs and renal contraindications, support adherence and consent."],["Irritable Bowel Syndrome","A patient with recurrent pain related to defecation has no alarm signs. Which initial dietary intervention is reasonable for constipation-predominant symptoms?","Soluble fibre:Can improve stool consistency and IBS symptoms.","Unrestricted wheat bran:Insoluble fibre may worsen bloating.","Routine lactose exclusion:Only useful when intolerance is suspected.","Prolonged fasting:Not an evidence-based initial strategy.","What bidirectional system contributes to IBS symptoms?","Gut brain axis","Functional gut-brain interaction; no mucosal inflammation expected. Blood, anaemia, nocturnal symptoms or weight loss need organic disease evaluation. Tailor treatment to bowel pattern."],["Liver Cirrhosis","A cirrhotic patient develops hepatic encephalopathy. Which class reduces intestinal ammonia absorption?","Non-absorbable disaccharide:Lactulose acidifies colon and promotes ammonia elimination.","Loop diuretic:Controls fluid overload but can worsen dehydration.","Proton pump inhibitor:Suppresses acid, not ammonia.","Beta blocker:May prevent variceal bleeding but does not treat encephalopathy.","Which nitrogenous compound contributes to encephalopathy?","Ammonia","Bridging fibrosis and regenerative nodules → portal hypertension and impaired synthesis. INR, albumin, bilirubin; look for infection, bleeding and constipation as encephalopathy triggers."],["Oral Candidiasis","An immunocompetent patient has mild localised scrapable oral plaques without dysphagia. Which class is appropriate topical therapy?","Polyene antifungal:Nystatin binds ergosterol and disrupts membranes.","Beta-lactam antibiotic:Targets bacteria, may predispose to candidiasis.","Topical corticosteroid:May worsen fungal infection.","Antiviral nucleoside analogue:Treats selected viral infections.","Which fungal membrane sterol is targeted by nystatin?","Ergosterol","Candida plaques scrape off; oral hairy leukoplakia does not. Dysphagia/odynophagia suggests oesophageal disease; consider HIV, diabetes, steroids. Rinse mouth after inhaled steroids."],["Pancreatitis","In acute pancreatitis with volume depletion, what is the initial supportive fluid class?","Isotonic crystalloid:Restores perfusion; reassess frequently to avoid overload.","Hypertonic saline:Reserved for selected sodium emergencies.","Hypotonic saline:Not preferred for initial resuscitation.","Routine colloid:Not standard first-line resuscitation.","Which enzyme activation initiates pancreatic autodigestion?","Trypsin;Trypsinogen activation","Epigastric pain radiating to back; diagnosis 2 of typical pain, lipase ≥3× ULN, imaging. Gallstones/alcohol common; early enteral nutrition when tolerated; no routine prophylactic antibiotics."],["Peptic Ulcer Disease","A patient with confirmed H. pylori ulcer receives eradication antibiotics. Which drug class improves healing and eradication efficacy?","Proton pump inhibitor:Suppresses acid via H+/K+ ATPase blockade.","Antimuscarinic:Not standard eradication therapy.","H1 receptor antagonist:Does not meaningfully suppress gastric acid.","Prokinetic:Does not eradicate H. pylori or adequately suppress acid.","Which enzyme helps H. pylori survive gastric acidity?","Urease","H. pylori urease → ammonia; NSAIDs reduce protective prostaglandins. PPI-based eradication per local resistance guidance; avoid NSAIDs. Sudden rigid abdomen suggests perforation."],["Severe Acute Malnutrition","A child with complicated severe acute malnutrition is admitted. Which initial feeding approach is appropriate?","Stabilisation formula F-75:Low initial protein and energy load for cautious stabilisation.","Catch-up formula F-100 immediately:Used after stabilisation, not during early unstable phase.","Standard unrestricted feeding:May precipitate metabolic complications.","High-protein supplements alone:Do not address stabilisation needs.","What electrolyte often falls in refeeding syndrome?","Phosphate;Hypophosphataemia","MUAC <115 mm (6–59 months) or severe wasting/bilateral pitting oedema. Prevent hypoglycaemia/hypothermia, cautious fluids and feeding; infection may be occult. Iron delayed until rehabilitation."],["Shigellosis","A child has fever and bloody diarrhoea due to suspected Shigella. Which management principle is appropriate?","Rehydration plus indicated antibiotic:Clinical dysentery needs assessment and locally guided antimicrobial treatment.","Antimotility treatment alone:May worsen invasive diarrhoea.","Rehydration withheld until culture:Delay increases dehydration risk.","Routine corticosteroid:Not treatment for bacterial dysentery.","What bacterial toxin inhibits the 60S ribosome?","Shiga toxin","Low infectious dose; fecal-oral transmission; invasion of colonic epithelium. Shiga toxin can cause HUS (especially S. dysenteriae type 1). Hand hygiene; monitor urine output."],["Ulcerative Colitis","Mild to moderate active left-sided UC without systemic toxicity. Which anti-inflammatory class is commonly first-line?","Aminosalicylate:Mesalazine reduces mucosal inflammation.","Systemic corticosteroid:Used for induction when more severe or refractory, not maintenance.","Anti-TNF biologic:For selected moderate-severe disease, not typical first-line mild disease.","Antibiotic:Not routine therapy for uncomplicated UC inflammation.","What histological finding consists of neutrophils within colonic crypts?","Crypt abscesses;Crypt abscess","Continuous mucosal inflammation from rectum, bloody diarrhoea; contrast Crohn skip/transmural. Severe systemic toxicity/distension → toxic megacolon risk. Avoid antimotility agents in severe colitis."],["Upper GI Bleed","A patient has haematemesis, hypotension and tachycardia. Which first action is safest?","ABCDE and urgent resuscitation:Restore perfusion, obtain IV access and senior help before endoscopy.","Oral PPI and discharge:Unsafe in haemodynamic instability.","Immediate outpatient endoscopy:Unstable patient needs resuscitation first.","Wait for haemoglobin trend:Acute blood loss can initially have normal Hb.","Which mediator stimulates acid secretion via H2 receptors?","Histamine","Melena, haematemesis; urea may rise due to blood digestion. PPI for suspected nonvariceal bleeding as indicated; suspected variceal bleed → vasoactive drug and antibiotics per protocol; urgent endoscopy after stabilisation."],["Anterior cruciate ligament Injury","After a pivot injury with immediate swelling, which examination most directly assesses ACL integrity?","Lachman test:Assesses anterior tibial translation at slight knee flexion.","Posterior drawer:Assesses PCL integrity.","Valgus stress:Assesses medial collateral ligament.","McMurray test:Assesses meniscal injury.","Which tibial movement is restrained by ACL?","Anterior translation;Anterior tibial translation","Pop, rapid haemarthrosis, instability; neurovascular exam and exclude fracture. Analgesia, protected weight bearing, rehabilitation/orthopaedic review."],["Bone Tumour (Osteosarcoma)","An adolescent has progressive distal femoral pain and an aggressive bone lesion. What is the safest next step?","Urgent tumour referral:Biopsy planning affects definitive limb surgery.","Unplanned local excision:May contaminate tissue planes.","Routine physiotherapy:Delays assessment of malignancy.","Empirical antibiotics only:Does not establish a tumour diagnosis.","What matrix is produced by malignant cells?","Osteoid;Malignant osteoid","Metaphysis around knee; sunburst periosteal reaction and Codman triangle can occur. Chest staging for lung metastases; do not perform unplanned biopsy."],["Fractures (long bone, closed)","After a tibial fracture, escalating pain on passive toe stretch occurs despite palpable pulses. What is the next step?","Urgent surgical review:Perfusion can fail before pulses disappear.","Routine fracture clinic review:Delays limb-saving care.","Increase analgesia alone:Masks progression without treating pressure.","Apply tighter circumferential cast:Can further increase compartment pressure.","Which nerve is at risk in humeral shaft fractures?","Radial nerve","Pain out of proportion/passive stretch → compartment syndrome; pulses may remain. Assess distal pulses, sensation, movement before/after splinting; femur fracture can cause major bleeding."],["Gout","A patient has recurrent gout attacks and is now between flares. Which class lowers urate production for long-term control?","Xanthine oxidase inhibitor:Allopurinol inhibits uric acid synthesis.","NSAID:Treats acute inflammation, does not lower urate production.","Colchicine:Inhibits microtubules and neutrophil activity, not urate synthesis.","Corticosteroid:Suppresses inflammation, not urate production.","Which crystal is found in gout?","Monosodium urate;Urate crystals","Needle-shaped negatively birefringent crystals; NLRP3 → IL-1β. Acute NSAID/colchicine/steroid according to contraindications; exclude septic arthritis even with crystals."],["Osteoarthritis","A patient has localised knee OA and wants a drug with less systemic exposure. Which class is reasonable initially?","Topical NSAID:Local pain relief with lower systemic exposure than oral NSAID.","Systemic corticosteroid:Not routine chronic OA treatment.","DMARD:Targets inflammatory arthritis, not OA.","Long-term opioid:Not preferred routine management due to harm.","Which cartilage component is progressively lost?","Articular cartilage;Hyaline cartilage","Mechanical pain worse with activity, short morning stiffness, osteophytes and joint space narrowing. Exercise, weight management; avoid unnecessary imaging for typical presentation."],["Osteoporosis","A patient with confirmed osteoporosis and high fracture risk has no contraindications. Which antiresorptive class is commonly first-line?","Bisphosphonate:Inhibits osteoclast-mediated resorption.","Loop diuretic:Increases urinary calcium loss.","Systemic glucocorticoid:Increases fracture risk with prolonged use.","NSAID:Analgesic only, no fracture prevention.","Which cell resorbs bone?","Osteoclast;Osteoclasts","Fragility fracture, DXA T-score ≤−2.5 in appropriate population. Weight-bearing exercise, fall prevention, adequate calcium/vitamin D. Correct hypocalcaemia before antiresorptives."],["Rheumatoid Arthritis","New persistent symmetrical inflammatory small-joint arthritis is confirmed. Which class modifies disease progression?","Conventional DMARD:Methotrexate is a common anchor drug; monitoring and pregnancy precautions apply.","NSAID:Symptomatic relief but does not prevent erosions.","Opioid:Analgesic only.","Antibiotic:Does not treat autoimmune synovitis.","What destructive synovial tissue erodes cartilage and bone?","Pannus","Morning stiffness >1 hour often, MCP/PIP, anti-CCP relatively specific. Early DMARD referral, monitor blood counts/liver; methotrexate is antifolate, weekly not daily."],["Septic Arthritis","An acutely hot swollen knee with fever is suspected of being infected. Which investigation is most decisive?","Synovial fluid aspiration:Culture, cell count and crystals help distinguish infection.","Serum urate:May be normal in gout and cannot exclude infection.","Plain radiograph:May be normal early.","Rheumatoid factor:Not useful for confirming acute joint infection.","Which bacterium is a common cause in adults?","Staphylococcus aureus;S aureus","Urgent drainage and empiric antibiotics after cultures if feasible, without delaying sepsis treatment. Crystals do not exclude infection. Neutrophilic suppurative inflammation."],["Spinal Cord Injury","After trauma, hypotension and bradycardia occur with warm skin. What mechanism explains this pattern?","Loss of sympathetic tone:Neurogenic shock causes vasodilation and unopposed vagal activity.","Acute blood loss:Usually causes tachycardia and cool skin.","Spinal shock alone:Describes transient reflex loss, not necessarily haemodynamic shock.","Cardiac tamponade:Obstructive shock usually causes tachycardia.","What term describes transient loss of reflexes below injury?","Spinal shock","ABCDE with spinal motion restriction and urgent trauma team; exclude haemorrhage before attributing hypotension to neurogenic shock. Assess motor, sensory, sacral function."],["Vitamin D Deficiency","A patient with nutritional vitamin D deficiency and intact renal activation needs replacement. Which agent class is appropriate?","Native vitamin D:Cholecalciferol replenishes substrate for activation.","Bisphosphonate:Does not correct vitamin D deficiency.","Loop diuretic:May increase calcium loss.","Calcimimetic:Suppresses PTH but does not replenish vitamin D.","What enzyme activates vitamin D in kidney?","1 alpha hydroxylase;1α hydroxylase;CYP27B1","Low 25-OH vitamin D; secondary PTH elevation, low phosphate and raised ALP may occur. Osteomalacia = defective mineralisation, unlike osteoporosis."],["Aplastic Anaemia","A patient with pancytopenia has fever and severe neutropenia. What is the safest initial response?","Urgent febrile neutropenia care:Prompt senior assessment and empirical IV antibiotics per protocol.","Oral iron and follow-up:Does not treat marrow failure or infection risk.","Wait for marrow biopsy:Unsafe delay when infection is suspected.","Routine platelet transfusion only:Does not address neutropenic sepsis.","What marrow cellularity is typical?","Hypocellular;Hypocellular marrow","Pancytopenia, low reticulocytes, hypocellular fatty marrow; often no splenomegaly. Bleeding and neutropenic infection are emergencies. Definitive immunosuppression/transplant specialist-led."],["Breast Cancer","A suspicious breast mass is found. Which investigation establishes histology?","Core needle biopsy:Provides tissue architecture and receptor testing.","Mammography alone:Imaging estimates suspicion but does not confirm histology.","CA 15-3:Not diagnostic screening for a breast lump.","Ultrasound alone:Characterises lesion but cannot establish pathology.","Which receptor predicts benefit from tamoxifen?","Oestrogen receptor;Estrogen receptor;ER","Triple assessment: clinical, imaging, biopsy. Hard fixed irregular mass, peau d’orange from dermal lymphatic obstruction. Endocrine therapy for ER-positive disease; stage/subtype guide treatment."],["Cervical Cancer","A woman has postcoital bleeding and a visible suspicious cervical lesion. What is the appropriate next action?","Urgent biopsy referral:Symptomatic suspected cancer needs histology.","Routine screening smear only:Screening is not enough for a visible suspicious lesion.","Empirical vaginal antifungal:Does not evaluate malignancy.","Repeat screening in a year:Delays diagnosis.","Which HPV oncoprotein promotes p53 degradation?","E6;HPV E6","High-risk HPV 16/18; E6 inhibits p53, E7 inhibits RB. Transformation zone; HPV vaccination and screening prevent disease, symptomatic lesions require diagnostic work-up."],["Disseminated Intravascular Coagulation","A septic patient has diffuse bleeding, low platelets and prolonged PT/aPTT. What is the central treatment principle?","Treat the underlying trigger:Control sepsis to stop ongoing coagulation activation.","Vitamin K alone:Does not correct widespread factor consumption.","Antiplatelet treatment:May worsen bleeding.","Routine anticoagulation for everyone:Management depends on bleeding/thrombosis phenotype.","Which fibrin breakdown marker rises?","D dimer;D-dimer","Tissue factor/thrombin → microthrombi and consumption of platelets/factors. Low fibrinogen often, high D-dimer, prolonged PT/aPTT; blood products for clinically significant bleeding under supervision."],["Haemophilia","A boy with haemophilia A has acute haemarthrosis. Which replacement directly corrects the deficit?","Factor VIII concentrate:Replaces deficient clotting factor VIII.","Factor IX concentrate:Used for haemophilia B.","Vitamin K:Does not correct inherited factor VIII deficiency.","Platelet concentrate:Does not replace plasma factor VIII adequately.","What inheritance pattern is typical?","X linked recessive;X-linked recessive","Deep bleeding, haemarthroses, isolated prolonged aPTT, normal PT and platelets. Avoid IM injections and NSAIDs; specialist haemostasis plan."],["Iron Deficiency Anaemia","A stable adult with confirmed iron deficiency can absorb and tolerate tablets. Which initial replacement is appropriate?","Oral ferrous salt:Provides absorbable elemental iron.","Folate supplement:Treats folate deficiency, not iron deficiency.","Erythropoiesis stimulant:Not routine for uncomplicated iron deficiency.","Parenteral cobalamin:Treats B12 deficiency.","Which storage protein is low in uncomplicated iron deficiency?","Ferritin","Microcytic hypochromic, low ferritin/TSAT, high TIBC; inflammation may raise ferritin. Find cause, especially GI blood loss in men/postmenopausal women; iron replacement alone is insufficient."],["Kaposi Sarcoma","A patient with untreated HIV and limited cutaneous Kaposi sarcoma is clinically stable. Which underlying disease treatment is foundational?","Combination ART:Immune restoration can improve HIV-associated KS.","Systemic corticosteroid:May worsen KS.","Antifungal therapy:Does not treat HHV-8 associated tumour.","Anticoagulation:Does not treat vascular tumour proliferation.","Which virus causes Kaposi sarcoma?","HHV8;HHV-8;KSHV","Violaceous lesions, spindle cells and slit-like vascular spaces; HHV-8. Assess oral/visceral disease; ART and oncology review for extensive/symptomatic disease."],["Thalassaemia","A transfusion-dependent patient develops iron overload. Which class addresses this complication?","Iron chelator:Binds excess iron for elimination.","Oral iron:Worsens overload without proven deficiency.","Erythropoietin:Does not remove stored iron.","Folate antagonist:Impairs DNA synthesis and is not chelation.","What haemoglobin fraction is commonly elevated in beta-thalassaemia trait?","HbA2;Haemoglobin A2","Reduced globin synthesis → microcytosis, target cells, ineffective erythropoiesis. Beta trait often high HbA2; distinguish from iron deficiency using iron studies. Genetic counselling."],["Von Willebrand Disease","A patient with known responsive mild type 1 VWD needs a minor procedure. Which drug promotes endothelial release of VWF?","Desmopressin:Releases stored VWF and factor VIII; suitability depends on subtype.","Vitamin K:Supports synthesis of vitamin K-dependent factors only.","Heparin:Anticoagulates and worsens bleeding risk.","Aspirin:Impairs platelet function.","Which platelet receptor binds VWF during adhesion?","GPIb;Glycoprotein Ib;GP Ib","Mucocutaneous bleeding; VWF mediates adhesion and stabilises VIII. PT usually normal; aPTT may be normal. Desmopressin not suitable for all subtypes; tranexamic acid/VWF concentrate as indicated."]];
const themes=[["Which daily habit would most directly reduce recurrent dehydration-related kidney injury in this outdoor worker?","Drink water regularly:Replace fluid losses during heat exposure.","Restrict fluids at work:Increases volume depletion.","Take ibuprofen before work:May worsen renal perfusion.","Increase salt without water:Does not correct volume loss.","Prevention"],["A patient misses renal reviews because of taxi costs. What is the most appropriate response?","Explore transport support:Address barriers and arrange feasible follow-up.","Discharge for missed visits:Risks loss of continuity.","Require private transport:Increases inequity.","Repeat the same referral:Does not address the barrier.","Health systems"],["Which daily measure most directly detects recurrent fluid retention in stable heart failure?","Record morning weight:Rapid changes can indicate fluid accumulation.","Record evening temperature:Tracks fever rather than fluid accumulation.","Record weekly height:Height does not reflect fluid retention.","Record fasting glucose:Useful in diabetes, not specific to congestion.","Patient-centred care"],["A validated home BP monitor reads high, but the patient uses a very small cuff. What should be done?","Repeat with correct cuff:An undersized cuff may overestimate pressure.","Average the uncorrected readings:Does not remove systematic measurement error.","Treat a single reading:Diagnosis requires appropriate measurement and context.","Discard all home monitoring:Validated home measurements can be useful.","Digital health"],["The patient refuses a recommended renal biopsy after understanding benefits and risks. Which principle is most relevant?","Autonomy:Respect informed refusal by a capable adult.","Beneficence:Promotes benefit but does not override informed refusal.","Justice:Concerns fair access and resource allocation.","Confidentiality:Protects patient information.","Ethics"],["Two patients need urgent renal reviews but only one slot is available. Which principle supports prioritising clinical severity?","Justice:Fairly allocate resources according to clinical need.","Autonomy:Concerns individual choices.","Confidentiality:Protects private information.","Veracity:Concerns honesty.","Ethics / health systems"],["The patient asks whether PSA alone proves cancer. What is the best response?","Explain PSA limitations:Benign disease can elevate PSA; further assessment is needed.","Promise it is diagnostic:Overstates test specificity.","Withhold the result:Undermines informed decision-making.","Order treatment immediately:PSA alone is insufficient for diagnosis.","Communication"],["After recovery from a calcium oxalate stone, which daily habit most generally reduces recurrence?","Maintain fluid intake:Adequate urine volume lowers supersaturation.","Avoid dietary calcium entirely:May increase intestinal oxalate absorption.","Increase sodium intake:Can increase urinary calcium.","Use vitamin C megadoses:May increase oxalate production.","Prevention"],["A student notices a delayed antibiotic order in a deteriorating septic patient. What should they do?","Escalate immediately:Rapid team communication reduces treatment delays.","Wait until handover:Unsafe in deterioration.","Edit the prescription alone:May exceed student scope.","Document without escalation:Documentation alone does not address urgent risk.","Teamwork"],["A patient with photosensitive lupus asks about daily prevention of skin flares. What is most appropriate?","Use sun protection:UV exposure can trigger cutaneous disease activity.","Use tanning lamps:UV exposure can aggravate disease.","Avoid all exercise:Does not prevent photosensitive flares.","Stop antimalarial treatment:May increase flare risk.","Prevention"],["Which household intervention best reduces faecal-oral transmission?","Handwashing with soap:Interrupts transfer of enteric pathogens.","Sharing drinking cups:Can increase exposure.","Stopping breastfeeding:Removes protective nutrition and is not advised.","Using antibiotics routinely:Not appropriate prophylaxis for contacts.","Public health"],["The patient struggles to understand the fluid and salt advice. Which method checks comprehension?","Teach-back:Ask them to explain the plan in their own words.","Ask yes-or-no questions:May not assess comprehension.","Provide technical leaflets only:May not match literacy needs.","Ask a family member instead:May exclude the patient.","Communication"],["A patient with RUQ pain needs ultrasound but the local clinic lacks equipment. What is the safest response?","Arrange appropriate referral:Maintains access to required assessment.","Delay until equipment arrives:May delay necessary care.","Prescribe indefinite analgesia:Does not address potential acute disease.","Request screening endoscopy:Not appropriate for suspected gallbladder disease.","Health systems"],["A faecal blood test has high sensitivity for a target condition. What does high sensitivity mean?","Few false negatives:Most affected patients test positive.","Few false positives:Describes high specificity.","High positive predictive value:Depends partly on disease prevalence.","High negative predictive value:Also depends on prevalence.","Evidence-based practice"],["Which daily behavioural intervention can promote a regular bowel habit?","Schedule toileting after meals:Uses the gastrocolic reflex.","Suppress defecation urges:May worsen constipation.","Reduce dietary fluids:Can harden stool.","Use prolonged bed rest:Reduced activity may worsen bowel motility.","Prevention"],["Several cases of acute watery diarrhoea appear in one village. Which measure tracks new cases over time?","Incidence:Counts new cases in an at-risk population over time.","Prevalence:Counts existing cases.","Case fatality:Measures deaths among cases.","Specificity:Measures true negatives among unaffected people.","Public health"],["Several diners become ill after one event. What is the most appropriate public-health action?","Notify outbreak team:Supports investigation and control of a shared exposure.","Treat only the index diner:Misses a possible outbreak.","Publish diners' identities:Breaches confidentiality.","Give all attendees antibiotics:Not justified without indication.","Public health"],["A patient recovering from biliary colic asks why elective referral is needed. Which response is best?","Discuss recurrence risk:Explain benefits and risks of definitive review.","Promise no recurrence:Misrepresents risk.","Insist without explanation:Undermines shared decision-making.","Offer antibiotics indefinitely:Not appropriate prevention.","Patient-centred care"],["Which daily behaviour can reduce nocturnal reflux symptoms?","Avoid late meals:Reduces reflux when lying down.","Lie flat after eating:May promote reflux.","Increase evening meal size:May aggravate reflux.","Take peppermint before bed:Can relax the lower oesophageal sphincter.","Prevention"],["A household uses untreated stream water. What is the most appropriate practical prevention measure?","Boil drinking water:Inactivates Giardia cysts when done correctly.","Rely on clear appearance:Clear water may still contain cysts.","Add sugar to water:Does not remove pathogens.","Store water uncovered:Risks recontamination.","Public health"],["The patient requests that HIV results not be disclosed to relatives. What principle is directly involved?","Confidentiality:Protect personal health information unless lawful exception applies.","Justice:Concerns fair allocation.","Beneficence:Promotes benefit, not specifically privacy.","Non-maleficence:Avoids harm, not the direct duty here.","Ethics"],["The patient feels dismissed when told tests are normal. What response best supports patient-centred care?","Validate their symptoms:IBS symptoms are real; explain the gut-brain mechanism.","Say symptoms are imagined:Invalidates the patient's experience.","Repeat all tests indefinitely:May cause unnecessary burden.","Avoid discussing stress:Misses relevant biopsychosocial factors.","Patient-centred care"],["A patient with alcohol-related cirrhosis is worried about discussing drinking. What response is most appropriate?","Use nonjudgmental counselling:Facilitates disclosure and support.","Threaten loss of treatment:Creates barriers and stigma.","Assume denial of dependence:Avoid assumptions.","Share history with neighbours:Breaches confidentiality.","Communication"],["An inhaled corticosteroid user has recurrent oral candidiasis. Which daily habit reduces recurrence?","Rinse mouth after inhalation:Removes residual steroid from oral mucosa.","Skip all inhalers:Can destabilise underlying asthma.","Brush immediately with sugar:Does not address steroid deposition.","Take antibiotics routinely:Can increase candidiasis risk.","Prevention"],["A clinician considers prophylactic antibiotics for uncomplicated pancreatitis. What supports avoiding unnecessary use?","Antimicrobial stewardship:Reduce avoidable harm and resistance when antibiotics lack indication.","Patient autonomy alone:Does not determine clinical indication.","Diagnostic sensitivity:Not the relevant prescribing principle.","Universal prophylaxis:Not evidence-based for uncomplicated pancreatitis.","Diagnostics and therapy"],["A patient with an NSAID-associated ulcer wants to continue self-medication. What is the safest counselling?","Review NSAID alternatives:Reduces risk of recurrent injury and bleeding.","Take NSAIDs with alcohol:Increases risk of harm.","Double the NSAID dose:Increases mucosal injury.","Ignore dark stools:Melena requires evaluation.","Prevention"],["A child's caregiver cannot afford adequate food. What is the best system-level intervention?","Link to nutrition support:Addresses food insecurity and continuity of care.","Give dietary advice alone:May not address affordability.","Blame caregiver decisions:Stigmatises without solving barriers.","Discontinue follow-up:Risks further deterioration.","Health systems"],["Which daily household habit is especially important after shigellosis?","Wash hands after toileting:Interrupts low-infectious-dose faecal-oral spread.","Use communal towels unwashed:May spread organisms.","Avoid all cooked meals:Does not address transmission.","Share utensils without washing:Can promote spread.","Prevention"],["A student is uncertain whether a patient with severe colitis is deteriorating. What should they do?","Escalate to supervisor:Recognise limits and possible toxic megacolon.","Wait for next appointment:May delay treatment.","Reassure without assessment:Unsafe with concerning symptoms.","Increase antidiarrhoeals alone:Can worsen severe colitis.","Clinical practice"],["A student is too fatigued to safely assist with a bleeding patient. What should they do?","Request supervised relief:Ensure safe handover and patient continuity.","Leave without handover:Disrupts emergency care.","Conceal fatigue:Increases risk of error.","Work beyond competence:Unsafe for patient and student.","Student wellness"],["An athlete wants to return to sport immediately after suspected ACL injury. What is best?","Discuss graded rehabilitation:Return depends on stability, recovery and supervised assessment.","Promise immediate full recovery:Overstates prognosis.","Recommend immobilisation forever:May impair function.","Ignore instability symptoms:Risks further injury.","Patient-centred care"],["A teenager asks whether an aggressive bone lesion proves cancer. What is appropriate?","Explain diagnostic uncertainty:Imaging is concerning but histology is needed.","Guarantee a benign result:False reassurance.","Announce definite cancer:Overstates certainty before histology.","Avoid involving the patient:Undermines age-appropriate communication.","Communication"],["After splinting, a patient reports increasing numbness. Which action best promotes safety?","Repeat neurovascular checks:Detect new compromise and escalate urgently.","Wait for routine radiographs:May delay treatment.","Record only the pain score:Misses neurological deterioration.","Tighten the splint:May worsen compression.","Clinical practice"],["Which modifiable daily habit can reduce gout flares in a person drinking beer heavily?","Reduce alcohol intake:Alcohol can raise urate and precipitate attacks.","Increase sugary drinks:Fructose can raise urate.","Start fasting frequently:May precipitate flares.","Stop prescribed urate therapy:May destabilise urate control.","Prevention"],["Which non-drug intervention is appropriate for overweight patients with knee osteoarthritis?","Graded exercise:Strengthening and activity improve function; weight reduction also helps.","Prolonged bed rest:Can worsen weakness.","Avoid all weight-bearing:May reduce function unnecessarily.","Routine high-dose opioids:Not a first-line non-drug approach.","Prevention"],["An older adult with osteoporosis has loose rugs and poor lighting. What is the most relevant prevention action?","Reduce household trip hazards:Fall prevention lowers fracture risk.","Avoid all walking:Can worsen deconditioning.","Restrict dietary calcium:May impair bone health.","Use sedatives routinely:Can increase fall risk.","Prevention"],["A patient on methotrexate has trouble accessing blood monitoring. What is the best response?","Arrange accessible monitoring:Supports medication safety and continuity.","Continue without monitoring:Risks undetected toxicity.","Double the dose at visits:Unsafe and not a substitute.","Stop follow-up entirely:Risks uncontrolled disease.","Health systems"],["A joint aspirate result is pending but the patient is becoming hypotensive. What is the safest approach?","Escalate suspected sepsis:Do not delay emergency care for microbiology.","Await final cultures:May delay life-saving treatment.","Provide oral analgesia alone:Does not address deterioration.","Repeat outpatient examination:Unsafe in instability.","Patient safety"],["A student must transfer a trauma patient with possible spinal injury. What is most appropriate?","Use coordinated team transfer:Maintain spinal motion restriction and communication.","Ask the patient to stand:May worsen injury.","Transfer alone without support:Increases unsafe movement.","Delay all ABC assessment:Airway and breathing remain priorities.","Teamwork"],["A patient asks whether a low vitamin D blood result means osteoporosis. What should be explained?","Distinguish mineralisation from density:Vitamin D deficiency can cause osteomalacia; osteoporosis is a separate diagnosis.","Treat the terms as identical:Confuses distinct pathology.","Use ALP alone for diagnosis:Not definitive for osteoporosis.","Ignore fracture history:Relevant to bone assessment.","Biomedical sciences"],["A patient with marrow failure asks why prompt fever reporting matters. Which explanation is best?","Neutropenia raises infection risk:Serious infection can progress rapidly.","Anaemia causes bacterial growth:Anaemia alone does not explain susceptibility.","Platelets destroy bacteria:Not their principal function.","Fever reliably excludes sepsis:Sepsis can occur without fever.","Communication"],["A patient wants to discuss treatment options with a trusted relative. Which action is best?","Ask permission to involve them:Respect patient preferences and privacy.","Disclose without consent:May violate confidentiality.","Exclude all relatives:May undermine chosen support.","Decide treatment without patient:Undermines autonomy.","Patient-centred care"],["Which population intervention most directly prevents HPV-related cervical cancer?","HPV vaccination:Reduces infection by targeted oncogenic HPV types.","Routine antibiotic prophylaxis:Does not prevent HPV infection.","Universal hysterectomy:Unnecessary and harmful.","Avoid cervical screening:Misses precancerous disease.","Public health"],["A student notices incompatible blood products being prepared. What should they do?","Stop and escalate immediately:Prevent harm and verify compatibility with the team.","Proceed because already ordered:Risks transfusion harm.","Discard products independently:Follow local blood bank procedures.","Wait until the infusion ends:Unsafe delay.","Patient safety"],["A child with haemophilia participates in sport. What is appropriate counselling?","Plan safer activity:Encourage activity with individual bleeding-risk advice.","Avoid all physical activity:May cause deconditioning.","Ignore bleeding symptoms:May delay treatment.","Use aspirin before exercise:Can increase bleeding risk.","Patient-centred care"],["A man with iron deficiency has no access to endoscopy locally. What is best?","Arrange timely referral:Investigate possible GI blood loss despite access barriers.","Treat iron indefinitely alone:May miss underlying pathology.","Reassure after Hb improves:Improvement does not exclude malignancy.","Stop iron before arranging care:Not the key access intervention.","Health systems"],["A patient with visible Kaposi lesions fears discrimination. What is best?","Offer confidential support:Address stigma and link to appropriate HIV/oncology care.","Disclose diagnosis publicly:Violates confidentiality.","Avoid discussing treatment:May reduce engagement.","Assume refusal of care:Stigmatising assumption.","Professionalism"],["Parents of a child with beta-thalassaemia ask about future pregnancies. What is most appropriate?","Offer genetic counselling:Explain inheritance and available reproductive options without coercion.","Tell them not to conceive:Violates reproductive autonomy.","Assume all children affected:Risk depends on parental genotypes.","Avoid discussing inheritance:Misses an informed decision opportunity.","Patient-centred care"],["A patient with VWD is using aspirin for mild pain. Which principle supports checking alternatives?","Non-maleficence:Avoid preventable bleeding harm.","Justice:Concerns equitable access.","Autonomy:Supports informed choice but does not specifically describe harm prevention.","Confidentiality:Protects private health information.","Ethics"]];
const old=window.MED_EXTRA||[];
const base=old.filter(c=>typeof c.id==="number"&&c.id>=3000&&c.id<3100&&Array.isArray(c.questions));
const tidy=s=>String(s||"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
const make=(stem,items,skill,seed)=>{const parsed=items.map(x=>{const i=x.indexOf(":");return {o:x.slice(0,i),why:x.slice(i+1)}});const order=[1,2,3];if(seed%2)order.reverse();if(seed%3===0)order.push(order.shift());order.splice(Math.floor(seed/4)%4,0,0);return {type:"SBA",q:stem,options:order.map(i=>parsed[i].o),answer:"ABCD"[order.indexOf(0)],explain:parsed[0].why,whyOptions:order.map(i=>parsed[i].why),skill}};
const sprint=[],pearls={};
rows.forEach((r,i)=>{const [name,stem,...rest]=r;const [a,b,c,d,vq,va,pearl]=rest;const [answer,...accepted]=va.split(";");const original=base.find(x=>tidy(x.core)===tidy(name));if(!original)return;
const oq=original.questions,theme=themes[i];
const drug=make(stem,[a,b,c,d],"First-line / bedside / safe action",881+i*997);
const vertical=make(theme[0],theme.slice(1,5),theme[5],991+i*613);
const data=oq.find(x=>x.isData)||oq[5],recognition=oq[0],mechanism=oq[1],safety=oq[4],short=oq.find(x=>x.type==="VSAQ");
const qs=[recognition,mechanism,drug,safety,vertical,data,short,{type:"VSAQ",q:vq,answer,accepted,explain:pearl,skill:"High-yield mechanism / VSAQ"}].filter(Boolean).map((q,j)=>({...q,number:j+1}));
sprint.push({id:5000+i,title:"Paper 2 sprint · "+name,module:original.module,core:name,scenario:original.scenario,source:"Paper 2 sprint · Wits-style supplemental educational practice (not official questions); adapted existing vignette plus new targeted items",difficulty:"Challenge",questions:qs,sprint:true});
pearls[name]={pearl,focus:a.replace(":", " — "),vsaq:vq,answer,clusterId:5000+i};
});
for(const n of (window.MED_NOTES||[])){if(pearls[n.name])n.sprintPearl=pearls[n.name];}
window.MED_P2_PEARLS=pearls;window.MED_P2_SPRINT=sprint;window.MED_EXTRA=old.concat(sprint);
})();